CREATE TYPE "role_utilisateur" AS ENUM (
  'Collaborateur',
  'Assistant_RH'
);

CREATE TYPE "statut_souhait" AS ENUM (
  'EN_ATTENTE_VALIDATION',
  'INSCRIT',
  'MIS_EN_ATTENTE',
  'DESINSCRIT'
);

CREATE TABLE "service" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nom" varchar(100) UNIQUE NOT NULL
);

CREATE TABLE "utilisateur" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "matricule" varchar(20) UNIQUE NOT NULL,
  "nom" varchar(100) NOT NULL,
  "prenom" varchar(100) NOT NULL,
  "email" varchar(255) UNIQUE NOT NULL,
  "mot_de_passe" varchar(255) NOT NULL,
  "role" role_utilisateur NOT NULL DEFAULT 'Collaborateur',
  "service_id" bigint NOT NULL
);

CREATE TABLE "campagne" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "annee" integer UNIQUE NOT NULL,
  "date_etablissement" date NOT NULL,
  "date_ouverture" date NOT NULL,
  "date_cloture" date NOT NULL,
  "date_publication" date NOT NULL
);

CREATE TABLE "formation" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "campagne_id" bigint NOT NULL,
  "intitule" varchar(200) NOT NULL,
  "description" text,
  "nb_places" integer NOT NULL,
  "est_validee" boolean NOT NULL DEFAULT false,
  "date_validation" timestamp,
  "valide_par_id" bigint
);

CREATE TABLE "formation_service_prioritaire" (
  "formation_id" bigint NOT NULL,
  "service_id" bigint NOT NULL,
  PRIMARY KEY ("formation_id", "service_id")
);

CREATE TABLE "demande" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "utilisateur_id" bigint NOT NULL,
  "campagne_id" bigint NOT NULL,
  "date_creation" timestamp NOT NULL DEFAULT (now()),
  "date_derniere_modif" timestamp NOT NULL DEFAULT (now())
);

CREATE TABLE "souhait" (
  "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "demande_id" bigint NOT NULL,
  "formation_id" bigint NOT NULL,
  "rang" smallint NOT NULL,
  "statut" statut_souhait NOT NULL DEFAULT 'EN_ATTENTE_VALIDATION',
  "date_decision" timestamp,
  "decide_par_id" bigint
);

CREATE UNIQUE INDEX ON "demande" ("utilisateur_id", "campagne_id");

CREATE UNIQUE INDEX ON "souhait" ("demande_id", "rang");

CREATE UNIQUE INDEX ON "souhait" ("demande_id", "formation_id");

ALTER TABLE "utilisateur" ADD FOREIGN KEY ("service_id") REFERENCES "service" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "formation" ADD FOREIGN KEY ("campagne_id") REFERENCES "campagne" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "formation" ADD FOREIGN KEY ("valide_par_id") REFERENCES "utilisateur" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "formation_service_prioritaire" ADD FOREIGN KEY ("formation_id") REFERENCES "formation" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "formation_service_prioritaire" ADD FOREIGN KEY ("service_id") REFERENCES "service" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "demande" ADD FOREIGN KEY ("utilisateur_id") REFERENCES "utilisateur" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "demande" ADD FOREIGN KEY ("campagne_id") REFERENCES "campagne" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "souhait" ADD FOREIGN KEY ("demande_id") REFERENCES "demande" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "souhait" ADD FOREIGN KEY ("formation_id") REFERENCES "formation" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "souhait" ADD FOREIGN KEY ("decide_par_id") REFERENCES "utilisateur" ("id") DEFERRABLE INITIALLY IMMEDIATE;
